const upper = (value:string) => value.toLocaleUpperCase("tr-TR");
const normalizeFieldValue = (key:string,type:FieldType,value:string) => type === "email" || key.toLowerCase().includes("email") || key.toLowerCase().includes("url") ? value.toLocaleLowerCase("en-US").trimStart() : ["text","textarea"].includes(type) ? upper(value) : value;
const numericInput = (type:FieldType,value:string) => {
  if(type === "number") return value.replace(/\D/g, "");
  if(type === "money") {
    const cleaned=value.replace(/[^\d.,]/g, "").replace(",", ".");
    const [whole,...fraction]=cleaned.split(".");
    return `${whole}${fraction.length?`.${fraction.join("").slice(0,2)}`:""}`;
  }
  return value;
};
const moneyValue = (value:string) => Number((value||"0").replace(",",".")) || 0;
