const formatDateInput = (value: string) => {
  const digits = value.replace(/\D/g, "").slice(0, 8);
  return [digits.slice(0, 2), digits.slice(2, 4), digits.slice(4, 8)].filter(Boolean).join(".");
};
const isoToDisplay = (value: string) => value ? value.split("-").reverse().join(".") : "";
const isValidDateDisplay = (value: string) => { const match=value.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);if(!match)return false;const d=Number(match[1]),m=Number(match[2]),y=Number(match[3]),date=new Date(y,m-1,d);return date.getFullYear()===y&&date.getMonth()===m-1&&date.getDate()===d; };
const downloadText = (name: string, content: string, type = "text/plain;charset=utf-8") => {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url);
};

